import com.luci.pianoroom.*;
public final class SceneIntegrationTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[]args)throws Exception {long bank=Synth.load(args[0]);Synth s=new Synth();s.setLayer(0,bank,0);s.setGain(0,.4f);if(args.length>1)s.backend(1);s.start();Thread.sleep(200);s.midi(0xB0,64,127);s.midi(0x90,60,100);Thread.sleep(100);check(s.voicesNow()[0]>0,"old note");ChannelSettings[] fx={new ChannelSettings(),new ChannelSettings(),new ChannelSettings(),new ChannelSettings()};fx[0].resonance=10;check(s.bankInUse(bank),"active bank retained");s.replaceScene(new long[]{bank,bank,bank,bank},new int[]{4,0,0,0},new float[]{.5f,0,0,0},fx,256,12,.8f,.25f,1);check(s.continuityDetails().contains("Canais anteriores: 1"),"old scene retained");s.midi(0x90,60,110);Thread.sleep(40);check(s.voicesNow()[0]>0,"new scene sounds");s.master(0);Thread.sleep(40);java.nio.ByteBuffer pcm=java.nio.ByteBuffer.allocateDirect(4096*4).order(java.nio.ByteOrder.LITTLE_ENDIAN);Synth.recordStart(s.sampleRate());Thread.sleep(45);int frames=Synth.recordRead(pcm,4096);Synth.recordStop();check(frames>0,"mute capture");for(int i=0;i<frames*2;i++)check(pcm.getShort(i*2)==0,"Master mutes new voices and old tails");s.master(.8f);Thread.sleep(35);Synth.recordStart(s.sampleRate());Thread.sleep(45);frames=Synth.recordRead(pcm,4096);Synth.recordStop();boolean sound=false;for(int i=0;i<frames*2;i++)sound|=pcm.getShort(i*2)!=0;check(sound,"Master restore keeps held sound");s.midi(0x80,60,0);s.midi(0x80,60,0);s.midi(0xB0,64,0);Thread.sleep(1500);s.collectTails();check(s.isRunning(),"still running");s.setGain(0,0);s.armSilent=true;s.midi(0x90,65,90);Thread.sleep(30);check(s.voicesNow()[0]>0,"silent arm holds note for XY");s.setGain(0,.3f);s.midi(0x80,65,0);s.panic();s.collectTails();check(s.continuityDetails().contains("Canais anteriores: 0"),"panic and tail GC");s.close();check(!s.bankInUse(bank),"closed scene releases bank use");Synth.freeBank(bank);System.out.println("Scene JNI integration: old/new voices, MIDI/pedal, silent-arm gain and tail ownership passed on simulated route");}
}
